import glob, os, flowio
base='/task/input/fcs/'
for path in sorted(glob.glob(base+'*.fcs')):
    fd=flowio.FlowData(path)
    keys=['FSC-A','FSC-H','SSC-A','V450-A','V525-A','B530-A','B710-A','YG586-A','YG780-A','R670-A','R780-A']
    vals={}
    for i in sorted(fd.channels):
        nm=fd.channels[i]['pnn']
        if nm in keys:
            vals[nm]=fd.text.get(f'p{i}v')
    print(os.path.basename(path), ' '.join(f'{k}={vals.get(k)}' for k in keys))
